set -eu
sudo -n mysql -NBe "SET SESSION group_concat_max_len=1048576;
SELECT 'audit_events',SHA2(GROUP_CONCAT(SHA2(CONCAT_WS('|',event_id,entity_type,entity_id,action,DATE_FORMAT(event_time,'%Y-%m-%d %H:%i:%s'),details),256) ORDER BY event_id SEPARATOR ':'),256) FROM legacy_shop.audit_events;
SELECT 'customers',SHA2(GROUP_CONCAT(SHA2(CONCAT_WS('|',customer_id,external_ref,full_name,email,status,DATE_FORMAT(created_at,'%Y-%m-%d %H:%i:%s')),256) ORDER BY customer_id SEPARATOR ':'),256) FROM legacy_shop.customers;
SELECT 'orders',SHA2(GROUP_CONCAT(SHA2(CONCAT_WS('|',order_id,customer_id,order_ref,total_cents,status,DATE_FORMAT(created_at,'%Y-%m-%d %H:%i:%s')),256) ORDER BY order_id SEPARATOR ':'),256) FROM legacy_shop.orders;
SELECT 'order_items',SHA2(GROUP_CONCAT(SHA2(CONCAT_WS('|',order_id,line_no,sku,quantity,unit_price_cents),256) ORDER BY order_id,line_no SEPARATOR ':'),256) FROM legacy_shop.order_items;"

